textContent:
For any given number n, print Hollow and solid Squares and Rhombus made with stars(*). Examples:  

Input : n = 4
Output : 

Solid Square:
****
****
****
****

Hollow Square:
****
*  *
*  *
****

 



1. Solid Square : Solid Square is easiest among all given patterns. To print Solid square with n rows, we should use two loops iterating n times both. Where the outer loop is used for numbers of rows and the inner loop is used for printing all stars in a particular row.2. Hollow Square : Hollow Square requires a little bit improvisation. Here we should again use two loops, where 1st and last row must have all n-stars and remaining rows have stars only in 1st and last column.  



            C++

    // C++ program to print 
// hollow and solid square patterns

#include <bits/stdc++.h>
using namespace std;

// Function for hollow square
void hollowSquare(int rows)
{
    int i, j;
    for (i=1; i<=rows; i++)
    {
        // Print stars for each solid rows
        if (i==1 || i==rows)
            for (j=1; j<=rows; j++)
                cout << "*";

        // stars for hollow rows
        else
            for (j=1; j<=rows; j++)
                if (j==1 || j==rows)
                    cout << "*";
                else
                    cout << " ";

        // Move to the next line/row
        cout << "\n";
    }
}

// Function for Solid square
void solidSquare(int rows)
{
    int i, j;
    for (i=1; i<=rows; i++)
    {
        // Print stars after spaces
        for (j=1; j<=rows; j++)
            cout << "*";

        // Move to the next line/row
        cout << "\n";
    }

}

// Utility program to print all patterns
void printPattern(int rows)
{
    cout << "\nSolid Square:\n";
    solidSquare(rows);

    cout << "\nHollow Square:\n"; 
    hollowSquare(rows);
}

// Driver program
int main()
{
    int rows = 5;
    printPattern (rows);
    return 0;
}



